/* Loads and registers resources for the De-Barrier (Debaria) effect. */
// FUNCTION: FF7 0x00578520
void __cdecl BattleFx_MagicLoadResDeBarrier(void)
{
    GfxModelTableBank *poolPointer;
    GfxResourceRequest reqBuffer;
    int kind;
    char pathText[200];
    GfxResourceRequest *pRequest;
    int resourceTable;

    if (g_pBattle3dScene != 0 && g_BattleMagicDeBarrierLoadedResTable == 0) {
        kind = 1;
        resourceTable = (int)&g_BattleMagicDeBarrierResourceDefs;
        poolPointer = (GfxModelTableBank *)(g_pBattle3dScene->modelTableBank);
        pRequest = &reqBuffer;
        Gfx_InitResourceRequest(pRequest);
        pRequest->groupTag = 0;
        // STRING: FF7 0x008adb14
        pRequest->resourcePath = BattleFx_BuildResourcePath("magic/debaria", pathText);
        Gfx_LoadModelTableIfAbsent(kind, resourceTable, pRequest, &g_BattleMagicDeBarrierLoadedResTable, poolPointer);
    }
}

/* Entry point for the De-Barrier (Debaria) magic effect. */
// FUNCTION: FF7 0x005785b0
void __cdecl BattleFx_MagicEnterDeBarrier(int targetMask, int actorIdx)
{
    BattleFx_MagicLoadResDeBarrier();
    BattleFx_MagicBeginDeBarrier(targetMask, actorIdx);
}

/* Initializes De-Barrier (Debaria) effect tasks and audio. */
// FUNCTION: FF7 0x005785ca
void __cdecl BattleFx_MagicBeginDeBarrier(int targetMask, int actorIdx)
{
    *(int *)&g_BattleFxDrawListBufferTaskSlotPtr = (int)BATTLE_NEW_TASK_SLOT(BattleFx_SelectDrawListBuffer);
    Battle_CreateBitPatternCallbackTask(targetMask, actorIdx, 3, BattleFx_MagicSpawnDeBarrierPerTarget);
    g_BattleMagicDeBarrierTargetIndex = 0;
}

/* Spawns per-target De-Barrier (Debaria) shatter tasks. */
// FUNCTION: FF7 0x0057860d
void __cdecl BattleFx_MagicSpawnDeBarrierPerTarget(int actor)
{
    int value;
    BattleFxDeBarrierShatter *shatterPtr;
    int scaledExtent;
    BattleFxDeBarrierSpawnRecord *shatterTask;
    BattleFxDeBarrierFlashTask *flashTask;

    flashTask = (BattleFxDeBarrierFlashTask *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicDeBarrierFlashBillboardModelTask);
    shatterTask = (BattleFxDeBarrierSpawnRecord *)BATTLE_NEW_TASK_SLOT(BattleFx_MagicDeBarrierShatterModelTask);
    Battle_GetBoneWorldPos(actor, g_BattleActorRecords[actor].targetBone, (short *)((char *)flashTask + 4));
    *(Int64Pair *)((char *)shatterTask + 4) = *(Int64Pair *)((char *)flashTask + 4);
    shatterTask->yaw = g_BattleActorRecords[actor].yaw;
    flashTask->yaw = shatterTask->yaw;
    value = g_BattleActorRecords[actor].radius + 0xE0;
    if (value > 0x76C) {
        value = 0x76C;
    }
    shatterTask->zOffset = value;
    flashTask->angle = value;
    flashTask->angle += 0xFA;
    if (value > 0x4F2) {
        value = 0x4F2;
    }
    scaledExtent = value << 0xC;
    flashTask->extent = scaledExtent / 0x177;
    shatterTask->scaledExtent = scaledExtent / 0x1F4;
    shatterTask->targetIndex = actor;
    shatterTask->bufBank = *(short *)&g_BattleMagicDeBarrierTargetIndex;
    g_BattleMagicDeBarrierTargetIndex++;
    shatterPtr = (BattleFxDeBarrierShatter *)Gfx_GetPsxScratchpadPtr(0);
    shatterPtr->meshPayload = (int)&g_BattleMagicDeBarrierFragmentMeshDesc;
    shatterPtr->bufBank = shatterTask->bufBank;
    BattleFx_MagicDeBarrierInitShatterModel(shatterPtr);
    Battle_DispatchSfxOpcodeDirect(SOUND_SFX_PLAY_1, Battle_ComputeScreenPanFromPosition((char *)flashTask + 4), 0x7F);
}

/* Initializes shatter model geometry and fragment records for De-Barrier. */
// FUNCTION: FF7 0x005787aa
void __cdecl BattleFx_MagicDeBarrierInitShatterModel(BattleFxDeBarrierShatter *shatter)
{
    int fragBlock, vertBase;

    vertBase = shatter->meshPayload + 4;
    fragBlock = vertBase + *(int *)shatter->meshPayload;
    shatter->fragNo = 0;
    fragBlock += 8;
    fragBlock = BattleFx_MagicDeBarrierInitShatterFragments(shatter, vertBase, fragBlock);
}

/* Initializes fragment velocities and orientations from mesh vertices. */
// FUNCTION: FF7 0x005787f6
int __cdecl BattleFx_MagicDeBarrierInitShatterFragments(BattleFxDeBarrierShatter *shatter, int vertexBase, int fragList)
{
    BattleFxDeBarrierDrawOffsets *recordPtr;
    int positionY;
    int zCenter;
    BattleFxDeBarrierShatterFragment *vert;
    int index8, fragNo, seed, divVal, junk, bufBank, numFragments, dstAvgX;

    numFragments = *(int *)fragList;
    fragNo = shatter->fragNo;
    junk = 0xC;
    bufBank = shatter->bufBank;
    recordPtr = (BattleFxDeBarrierDrawOffsets *)(fragList + 4);
    divVal = 0x61A8;
    for (index8 = 0; index8 < numFragments; index8++) {
        vert = (BattleFxDeBarrierShatterFragment *)(vertexBase + recordPtr->vertexOffset0);
        dstAvgX = vert->positionX;
        positionY = vert->positionY;
        zCenter = vert->zCenter;
        vert = (BattleFxDeBarrierShatterFragment *)(vertexBase + recordPtr->vertexOffset1);
        dstAvgX += vert->positionX;
        positionY += vert->positionY;
        zCenter += vert->zCenter;
        vert = (BattleFxDeBarrierShatterFragment *)(vertexBase + recordPtr->vertexOffset2);
        dstAvgX += vert->positionX;
        positionY += vert->positionY;
        zCenter += vert->zCenter;
        dstAvgX = dstAvgX / 3;
        positionY = positionY / 3;
        zCenter = zCenter / 3;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].posX = dstAvgX;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].posY = positionY;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].posZ = zCenter;
        zCenter = zCenter * zCenter / divVal;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].depth = 0xA - zCenter;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].age = 0;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].angleZ = 0;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].angleY = 0;
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].angleX = 0;
        seed = rand();
        if ((seed & 0x800) != 0) {
            g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].spinX = (seed & 7) * 0xC;
        } else {
            g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].spinX = -((seed & 7) * 0xC);
        }
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].velY = 0;
        if ((seed & 0x204080) != 0) {
            g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].spinZ = (seed >> 3 & 7) * 0xC;
        } else {
            g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].spinZ = -((seed >> 3 & 7) * 0xC);
        }
        g_BattleMagicDeBarrierFragmentStates[bufBank].shards[fragNo].accelY = (zCenter + 8) * ((seed & 3) + 8);
        fragNo++;
        recordPtr = (BattleFxDeBarrierDrawOffsets *)((char *)recordPtr + 0x14);
    }
    shatter->fragNo = fragNo;
    return (int)recordPtr;
}

